    int            amount_delta;
    int            n;
    int            call_flags;
    int            bound_offset;
    int            cnt;
    unsigned char *g;

    amt = MOBY(moby)->unkB4;
    debug_print(D_L00_001E8F00,
                MOBY(moby)->oclass,
                ((short)MOBY(moby)->save_id),
                MOBY(moby)->unkB4,
                *(short *)(moby + 0xB6));
    if (moby[0xB1] == 0xFE) {
        return;
    }
    if (((short)MOBY(moby)->save_id) < 0) {
        return;
    }
    lvl = current_level_index;
    level_moby_killed[lvl][((short)MOBY(moby)->save_id) >> 5] |= 1 << (MOBY(moby)->save_id & 0x1F);
    D_L00_001BA4D0_lui[((short)MOBY(moby)->save_id) >> 5] |= 1 << (MOBY(moby)->save_id & 0x1F);
    D_L00_001BA5D0_lui.a[((short)MOBY(moby)->save_id)] = moby[0xB0] + 2;
    k = moby[0xB0];
